// Stillbilder til videoene (ffmpeg + opplasting til Labrador, gjenbrukes). Vises når autoplay er
// blokkert, f.eks. lav strømmodus på iPhone — ellers blir bakgrunnen/laget tomt.
async function videoPosters(cfg) {
  const out = {};
